          .from('user_profiles')
          .update({ last_login: new Date().toISOString() })
          .eq('id', signedInUser.id)
          .then(({ error: updateError }) => {
            if (updateError) {
              console.warn('[AuthContext] Failed to update last_login:', updateError);
            }
          });
