        const finalRole = userType === 'cliente' ? ('cliente' as UserRole) : role;

        const { error: profileError } = await supabase
          .from('user_profiles')
          .insert({
            id: newUser.id,
            full_name: fullName,
            role: finalRole,
            user_type: userType,
            is_active: true,
            company_name: companyName || null,
            client_id: clientId || null,
          });

        if (profileError) {
          console.error('Error creating user profile:', profileError);
          throw new Error('Failed to create user profile');
        }

        await fetchUserProfile(newUser.id);
      }
    } catch (error) {
      console.error('Sign up error:', error);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  /**
   * Sign out handler
   * Step 10: Added cache invalidation on logout
   */
  const handleSignOut = async (): Promise<void> => {
    setLoading(true);
    try {
      // Clear profile cache before signing out
      if (user?.id) {
        clearCachedProfile(user.id);
      } else {
        clearCachedProfile(); // Clear all cached profiles as fallback
      }

      const { error } = await supabaseSignOut();

      if (error) {
        throw new Error(error.message);
      }

      setUser(null);
      setSession(null);
      setUserProfile(null);
      setIsTransitioning(false);
    } catch (error) {
      console.error('Sign out error:', error);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  // Computed value for authentication status
  const isAuthenticated = !!user && !!session;

  const value: AuthContextType = {
    user,
    session,
    userProfile,
    loading,
    signIn: handleSignIn,
    signUp: handleSignUp,
    signOut: handleSignOut,
    isAuthenticated,
    revalidateSession,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

